<template><view class="page-heading"><view><view class="eyebrow">EVERY LITTLE STEP COUNTS</view><text class="page-title">你的小小成长，值得被看见</text><text class="page-subtitle">只和昨天的自己比，每一步都是进步。</text></view></view><view class="achievement-grid"><WPCard v-for="badge in badges" :key="badge.name" :variant="badge.earned?'normal':'muted'"><text class="badge-art" aria-hidden="true">{{badge.icon}}</text><text class="section-title">{{badge.name}}</text><text class="muted block">{{badge.description}}</text><text class="badge-status">{{badge.earned?'✓ 已达成':'○ 慢慢来'}}</text></WPCard></view><WPCard class="milestone-note"><text class="section-title">每个人都有自己的节奏</text><text class="muted block">这里没有排名，也没有错过就消失的奖励。休息过后，可以从原来的地方继续。</text></WPCard></template>
<script setup lang="ts">
import WPCard from '../../components/wp-card/WPCard.vue'
import {computed} from 'vue';import {useProfileStore} from '../../stores/profile';const profile=useProfileStore();const badges=computed(()=>[{name:'第一次出发',icon:'⚑',description:'完成一次真实学习',earned:profile.db.history.length>0},{name:'五位新朋友',icon:'Aa',description:'认识 5 个不同的单词',earned:Object.keys(profile.db.cards).length>=5},{name:'拼写小探索家',icon:'✎',description:'正确完成一次拼写或听写',earned:profile.db.history.some(a=>a.correct&&['spell','dictation'].includes(a.mode))},{name:'和老朋友再见',icon:'↻',description:'完成一次到期复习',earned:profile.db.history.some(a=>a.source==='review_due')},{name:'一起长大',icon:'✦',description:'任意伙伴达到 2 级',earned:Object.values(profile.db.pets).some(p=>p.level>=2)},{name:'三天的小坚持',icon:'♧',description:'累计学习 3 天，不要求连续',earned:profile.db.streakDates.length>=3}])</script>
